-- Step 23: emailing a sales document to the customer, and what became of each email.
-- track: A
--
-- The CREATE TABLE / index statements are generated by drizzle-kit from
-- src/modules/sales-email/schema.ts. The section marked "hand-written" is not managed by Drizzle.
-- Reverse with drizzle/down/0020_sales_document_emails.sql.
--
-- Sending an email goes to an outside service. The app writes the row first, as "sending", then
-- calls the service, then writes what happened: sent, failed, or unknown when the service gave no
-- clear answer. Nothing here posts, numbers or moves anything; the table is a log of messages.

-- ── generated by drizzle-kit ────────────────────────────────────────────────────────────────────

CREATE TABLE "sales_document_emails" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"document_id" uuid NOT NULL,
	"to_address" text NOT NULL,
	"subject" text NOT NULL,
	"status" text DEFAULT 'sending' NOT NULL,
	"provider" text,
	"provider_message_id" text,
	"error" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" uuid NOT NULL,
	"finished_at" timestamp with time zone,
	"finished_by" uuid,
	CONSTRAINT "sales_document_emails_tenant_id_id_key" UNIQUE("tenant_id","id"),
	CONSTRAINT "sales_document_emails_status_known" CHECK ("sales_document_emails"."status" in ('sending', 'sent', 'failed', 'unknown')),
	CONSTRAINT "sales_document_emails_finished" CHECK (("sales_document_emails"."status" = 'sending') = ("sales_document_emails"."finished_at" is null) and ("sales_document_emails"."status" = 'sending') = ("sales_document_emails"."finished_by" is null)),
	CONSTRAINT "sales_document_emails_to_format" CHECK (char_length("sales_document_emails"."to_address") between 3 and 254 and "sales_document_emails"."to_address" ~ '^[^@\s]+@[^@\s]+$' and "sales_document_emails"."to_address" ~ '^[!-~]+$' and "sales_document_emails"."to_address" !~ '[,<>]' and strpos("sales_document_emails"."to_address", chr(59)) = 0),
	CONSTRAINT "sales_document_emails_subject_length" CHECK (char_length(btrim("sales_document_emails"."subject")) between 1 and 200 and "sales_document_emails"."subject" !~ '[[:cntrl:]]'),
	CONSTRAINT "sales_document_emails_provider_length" CHECK (char_length("sales_document_emails"."provider") between 1 and 40),
	CONSTRAINT "sales_document_emails_message_id_length" CHECK (char_length("sales_document_emails"."provider_message_id") between 1 and 200),
	CONSTRAINT "sales_document_emails_error_length" CHECK (char_length("sales_document_emails"."error") between 1 and 300)
);
