CREATE POLICY sales_document_emails_select ON public.sales_document_emails FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = sales_document_emails.tenant_id AND d.id = sales_document_emails.document_id)
  );
--> statement-breakpoint
CREATE POLICY sales_document_emails_insert ON public.sales_document_emails FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager', 'salesperson')
    AND created_by = (SELECT app.current_user_id())
    AND created_at = now()
    AND status = 'sending'
    AND provider IS NULL AND provider_message_id IS NULL AND error IS NULL AND finished_at IS NULL AND finished_by IS NULL
    AND EXISTS (
      SELECT 1 FROM public.sales_documents d
      WHERE d.tenant_id = sales_document_emails.tenant_id AND d.id = sales_document_emails.document_id
        AND d.status = 'submitted' AND d.number IS NOT NULL)
  );
--> statement-breakpoint
CREATE POLICY sales_document_emails_update ON public.sales_document_emails FOR UPDATE TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager', 'salesperson')
    AND status IN ('sending', 'unknown')
    AND EXISTS (SELECT 1 FROM public.sales_documents d WHERE d.tenant_id = sales_document_emails.tenant_id AND d.id = sales_document_emails.document_id)
  )
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND status IN ('sent', 'failed', 'unknown')
    AND provider IS NOT NULL
    AND finished_at = now()
    AND finished_by = (SELECT app.current_user_id())
  );
